/** What the client earns from, current ones first. Kept per client, with or without a Self Assessment registration. */
export function listIncomeSources(db: Database, actor: Actor, clientRef: unknown): ClientIncomeSource[] {
  const client = clientForActor(db, refArg(clientRef), actor)
  return db.prepare('SELECT * FROM client_income_sources WHERE client_ref = ? ORDER BY active DESC, source_type, detail').all(client.ref) as ClientIncomeSource[]
}

